// /agents — generated by `pnpm gen:screen agents`. D-33: the AI agents (ChatGPT, Claude, any MCP client) the person
// allowed to work in OCS for them, and Disconnect: the agent's tokens stop working at once and a new connection
// asks for consent again. Every person sees only their own agents.
import { useEffect, useState } from 'react';
import { Button, Card, FormMessage, PageHeader, useI18n } from '@ocs/ui';
import { loadAgents, revokeAgentAccess, type ConnectedAgent } from '../api.ts';

export function AgentsPage() {
  const { t } = useI18n();
  const [agents, setAgents] = useState<ConnectedAgent[] | 'failed' | null>(null);
  const [version, setVersion] = useState(0);
  useEffect(() => {
    loadAgents().then(setAgents, () => {
      setAgents('failed');
    });
  }, [version]);
  const disconnect = async (clientId: string) => {
    if ((await revokeAgentAccess(clientId).catch(() => 'failed')) === 'ok') setVersion((v) => v + 1);
    else setAgents('failed');
  };
  return (
    <>
      <PageHeader eyebrow={`/ ${t('agents.title')}`} title={t('agents.title')} />
      <Card>
        <p>{t('agents.intro')}</p>
        {agents === null ? <p>{t('common.loading')}</p> : null}
        {agents === 'failed' ? <FormMessage tone="error">{t('agents.failed')}</FormMessage> : null}
        {Array.isArray(agents) && agents.length === 0 ? <p>{t('agents.none')}</p> : null}
        {Array.isArray(agents) && agents.length > 0 ? (
          <table className="ocs-table">
            <thead>
              <tr>
                <th scope="col">{t('agents.col.agent')}</th>
                <th scope="col">{t('agents.col.since')}</th>
                <th scope="col">{t('agents.col.do')}</th>
              </tr>
            </thead>
            <tbody>
              {agents.map((a) => (
                <tr key={a.clientId}>
                  <td>{a.name ?? a.clientId}</td>
                  <td>{a.since?.slice(0, 10) ?? '—'}</td>
                  <td>
                    <Button
                      type="button"
                      aria-label={`${t('agents.disconnect')}: ${a.name ?? a.clientId}`}
                      onClick={() => void disconnect(a.clientId)}
                    >
                      {t('agents.disconnect')}
                    </Button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : null}
      </Card>
    </>
  );
}
